sql_templates.signal_fetch:
SELECT symbol, signal, date_issued, price_at_issue 
FROM signals.signal_log 
WHERE date_issued >= CURRENT_DATE - INTERVAL '20 days';

read_only_sql.template:
SELECT symbol, signal, entry_low, entry_high, stop_loss, target_1, target_2 
FROM signals.signal_log 
WHERE date_issued >= CURRENT_DATE - INTERVAL '20 days';
